from PIL import Image
import numpy as np
for tag in ['000_initial','028_obs']:
 for cam in ['front','topview']:
  im=np.asarray(Image.open(f'/app/output/episode/{tag}/{cam}.png'))
  d=np.load(f'/app/output/episode/{tag}/{cam}_depth.npy')[0].astype(float)
  if cam=='front': roi=(175,103,212,130)
  else: roi=(105,52,150,76)
  x0,y0,x1,y1=roi; pts=[]
  for y in range(y0,y1):
   for x in range(x0,x1):
    rgb=im[y,x]
    if max(rgb)<115 and d[y,x]<1.42:
     pts.append((x,y,float(d[y,x])))
  p=np.array(pts)
  print(tag,cam,'n',len(p))
  if len(p):
   print('bbox',p[:,:2].min(0),p[:,:2].max(0),'centroid',p[:,:2].mean(0),'depth',p[:,2].mean())
   # x hist by row region
   print('row counts',[(y,int(((p[:,1]==y)).sum())) for y in range(int(p[:,1].min()),int(p[:,1].max())+1,3)])
